import type { Metadata } from 'next'
import Link from 'next/link'
import { redirect } from 'next/navigation'
import { Plus } from 'lucide-react'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { requirePersona } from '@/lib/auth/require-persona'
import { CampaignsHub } from '@/components/marketing/CampaignsHub'
import { ReferralDashboard } from '@/components/marketing/ReferralDashboard'
import { AudienceTab } from './_components/AudienceTab'
import { WaitlistTab } from './_components/WaitlistTab'
import { Button } from '@/components/ui/button'
import { PageShell } from '@/components/shared/PageShell'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageTabs } from '@/components/shared/PageTabs'
import { PageViews } from '@/components/shared/PageViews'
import { filterTabsForRole } from '@/components/shared/page-tabs-utils'
import type { PageTab } from '@/components/shared/PageTabs'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
// Types pending pnpm db:types
type CampaignType = string
type CampaignStatus = string
type CampaignChannel = string

export const metadata: Metadata = {
  title: 'Marketing — InkOS',
}

const MARKETING_TABS: PageTab[] = [
  {
    key: 'audience',
    label: 'Audience',
    href: '/marketing?tab=audience',
  },
  {
    key: 'campaigns',
    label: 'Campaigns',
    href: '/marketing?tab=campaigns',
  },
  {
    key: 'waitlist',
    label: 'Waitlist',
    href: '/marketing?tab=waitlist',
  },
  {
    key: 'referrals',
    label: 'Referral program',
    href: '/marketing?tab=referrals',
  },
]

const VALID_TABS = MARKETING_TABS.map((t) => t.key)

interface Props {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}

export default async function MarketingPage({ searchParams }: Props) {
  await requirePersona(['studio_owner'])
  const supabase = await createClient()

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const canManage = ['owner', 'admin'].includes(role)

  // S18 fix — plan gating removed per product direction. Sidebar STUDIO pill is
  // the only visual cue; marketing pages render for every plan. S19 will add
  // contextual upsell inside features (e.g., send-cap warning, referral quota).

  type RawCampaign = {
    id: string
    name: string
    type: string
    channel: string
    status: string
    sent_count: number
    open_count: number
    click_count: number
    scheduled_at: string | null
    sent_at: string | null
  }

  const [campaignsResult, referralCodesResult, clientsResult] = await Promise.all([
    supabase
      .from('marketing_campaigns')
      .select('id, name, type, channel, status, sent_count, open_count, click_count, scheduled_at, sent_at')
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    supabase
      .from('referral_codes')
      .select(`
        id, code, discount_type, discount_value, uses_count, max_uses, is_active,
        client:clients(id, first_name, last_name, email)
      `)
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false }),
    canManage
      ? supabase
          .from('clients')
          .select('id, first_name, last_name, email')
          .eq('studio_id', studioId)
          .is('archived_at', null)
          .order('first_name')
          .limit(200)
      : Promise.resolve({ data: [] }),
  ])

  const campaigns = ((campaignsResult.data ?? []) as unknown as RawCampaign[]).map((c) => ({
    id: c.id,
    name: c.name,
    type: c.type as CampaignType,
    channel: c.channel as CampaignChannel,
    status: c.status as CampaignStatus,
    sent_count: c.sent_count,
    open_count: c.open_count,
    click_count: c.click_count,
    scheduled_at: c.scheduled_at,
    sent_at: c.sent_at,
  }))

  type RawCode = {
    id: string
    code: string
    discount_type: string
    discount_value: number
    uses_count: number
    max_uses: number | null
    is_active: boolean
    client: { id: string; first_name: string; last_name: string; email: string } | null
  }

  const referralCodes = ((referralCodesResult.data ?? []) as unknown as RawCode[]).map((c) => ({
    id: c.id,
    code: c.code,
    discount_type: c.discount_type as 'percentage' | 'fixed',
    discount_value: c.discount_value,
    uses_count: c.uses_count,
    max_uses: c.max_uses,
    is_active: c.is_active,
    client: c.client,
  }))

  const clientOptions = (clientsResult.data ?? []).map((c) => ({
    id: c.id,
    display: `${c.first_name} ${c.last_name} (${c.email})`,
  }))

  const totalReferrals = referralCodes.length
  const totalRedemptions = referralCodes.reduce((sum, c) => sum + c.uses_count, 0)
  const topReferrers = referralCodes.filter((c) => c.uses_count > 0).length

  const params = await searchParams
  const rawTab = typeof params.tab === 'string' ? params.tab : undefined
  const activeKey = rawTab && VALID_TABS.includes(rawTab) ? rawTab : 'audience'

  // Global CTA — drawer mounts on any tab (M2 wires the drawer; for now links to
  // the campaign new page as a fallback). Visible on every tab per M1 spec.
  const newCampaignCta = canManage ? (
    <Button size="sm" render={<Link href="/marketing/campaigns/new" />}>
      <Plus className="h-3.5 w-3.5" aria-hidden="true" />
      New campaign
    </Button>
  ) : null

  return (
    <PageShell>
      <PageHeader
        title="Marketing"
        description="Reactivate, reward, never spam."
        {...(newCampaignCta ? { actions: newCampaignCta } : {})}
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(MARKETING_TABS, role as NavRole)}
          activeKey={activeKey}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
        />
      </PageViews>

      <div role="tabpanel" id={`tabpanel-${activeKey}`}>
        {activeKey === 'audience' && <AudienceTab />}
        {activeKey === 'campaigns' && (
          <CampaignsHub campaigns={campaigns} canManage={canManage} />
        )}
        {activeKey === 'waitlist' && <WaitlistTab />}
        {activeKey === 'referrals' && (
          <ReferralDashboard
            codes={referralCodes}
            totalReferrals={totalReferrals}
            totalRedemptions={totalRedemptions}
            topReferrers={topReferrers}
            clientOptions={clientOptions}
            canManage={canManage}
          />
        )}
      </div>
    </PageShell>
  )
}

'use client'

import { useState, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Megaphone } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { CampaignCard } from './CampaignCard'
import { EmptyState } from '@/components/shared/EmptyState'
import { cn } from '@/lib/utils'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import type { CampaignType, CampaignStatus, CampaignChannel } from '@/lib/supabase/types'

// Starter chips guide a first-time user toward common campaign types.
// On click they open the new campaign flow pre-seeded with the audience segment.
// Drawer wiring (M2) replaces the router.push with a sheet open.
const STARTER_CHIPS = [
  { label: 'We miss you', segment: 'inactive_90d' },
  { label: 'Next flash event', segment: 'all_clients' },
  { label: 'Birthday wishes', segment: 'birthday_month' },
] as const

interface Campaign {
  id: string
  name: string
  type: CampaignType
  channel: CampaignChannel
  status: CampaignStatus
  sent_count: number
  open_count: number
  click_count: number
  scheduled_at: string | null
  sent_at: string | null
}

interface CampaignsHubProps {
  campaigns: Campaign[]
  canManage: boolean
}

export function CampaignsHub({ campaigns, canManage }: CampaignsHubProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)
  const [sendTarget, setSendTarget] = useState<{ id: string; name: string } | null>(null)
  const [isSending, setIsSending] = useState(false)

  async function confirmDelete() {
    if (!deleteTarget) return
    setIsDeleting(true)
    try {
      const res = await fetch(`/api/marketing/campaigns/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error()
      toast.success(`Campaign deleted`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to delete campaign')
    } finally {
      setIsDeleting(false)
      setDeleteTarget(null)
    }
  }

  async function confirmSend() {
    if (!sendTarget) return
    setIsSending(true)
    try {
      const res = await fetch(`/api/marketing/campaigns/${sendTarget.id}/send`, { method: 'POST' })
      if (!res.ok) throw new Error()
      toast.success(`${sendTarget.name} queued to send`)
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to send campaign')
    } finally {
      setIsSending(false)
      setSendTarget(null)
    }
  }

  async function handleTogglePause(id: string, currentStatus: CampaignStatus) {
    const newStatus = currentStatus === 'active' ? 'paused' : 'active'
    try {
      const res = await fetch(`/api/marketing/campaigns/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (!res.ok) throw new Error()
      toast.success(newStatus === 'paused' ? 'Campaign paused' : 'Campaign resumed')
      startTransition(() => router.refresh())
    } catch {
      toast.error('Failed to update campaign')
    }
  }

  return (
    <div className="space-y-6">
      {campaigns.length === 0 ? (
        <div className="flex flex-col items-center">
          <EmptyState
            icon={Megaphone}
            title="No campaigns yet"
            description="Create your first campaign to start engaging clients via email or SMS."
            {...(canManage ? { cta: { label: 'Create campaign', href: '/marketing/campaigns/new' } } : {})}
          />
          {canManage && (
            <div className="mt-4 flex flex-wrap justify-center gap-2">
              {STARTER_CHIPS.map(({ label, segment }) => (
                <Button
                  key={segment}
                  variant="outline"
                  size="sm"
                  onClick={() => router.push(`/marketing/campaigns/new?segment=${segment}`)}
                  className={cn('border-l-2 border-l-[color:var(--color-rust)]')}
                >
                  {label}
                </Button>
              ))}
            </div>
          )}
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {campaigns.map((c) => (
            <CampaignCard
              key={c.id}
              id={c.id}
              name={c.name}
              type={c.type}
              channel={c.channel}
              status={c.status}
              sentCount={c.sent_count}
              openCount={c.open_count}
              clickCount={c.click_count}
              scheduledAt={c.scheduled_at}
              sentAt={c.sent_at}
              canManage={canManage}
              onSend={(id, name) => setSendTarget({ id, name })}
              onTogglePause={handleTogglePause}
              onDelete={(id, name) => setDeleteTarget({ id, name })}
            />
          ))}
        </div>
      )}

      {/* Delete dialog */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete campaign?</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete <strong>{deleteTarget?.name}</strong>? This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isDeleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Send dialog */}
      <AlertDialog open={!!sendTarget} onOpenChange={(open) => !open && setSendTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Send now?</AlertDialogTitle>
            <AlertDialogDescription>
              <strong>{sendTarget?.name}</strong> will be sent immediately to all matching clients.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isSending}>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmSend} disabled={isSending}>
              {isSending ? 'Queueing...' : 'Send campaign'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

